// Example 1: Default to "Guest" if the pointer is nil
func greetWithDefault(name *string) {
    if name == nil {
        name = new(string)
        *name = "Guest"
    }
    fmt.Printf("Hello, %s!\n", *name)
}

// Example 2: Using a wrapper function to simulate a default parameter
// Golang does not support default parameters natively in function signatures.
func greetWithNonNilDefault(name string) {
    if name == "" {
        name = "Guest"
    }
    fmt.Printf("Hello, %s!\n", name)
}
